\u004c\u0040\u0079\u0024\u0053\u0021\u0044\u0061\u006a\u0069\u0062\u005e\u0074\u004a\u007a\u0046\u0039\u0049\u0052\u0072\u003d\u003f\u002a\u0066\u0057\u0046\u0055\u0058\u0028\u007d\u0060\u004c\u0037\u007a\u0061\u0048\u0054\u005a\u0046\u003b\u0076\u002a\u007c\u006a\u0055\u0052\u0046\u005a\u0037\u007b\u004b\u007c\u0025\u0046\u004e\u006d\u002f\u007c\u0035\u0030\u0064\u003f\u0060\u006d\u003b\u002c\u002c\u0022\u0025\u005a\u0023\u0058\u0057\u006c\u006d\u004d\u006b\u0021\u007e\u005a\u0042\u0040\u0079\u004c\u003e\u0047\u0036\u0074\u007e\u0022\u0025\u0072\u0046\u002b\u0057\u0072\u002c\u006e\u005b\u004e\u003a\u0033\u0025\u003a\u0072\u0046\u0057\u0056\u0061\u0071\u0032\u0050\u006f\u0071\u0042\u002a\u0079\u005b\u007e\u0052\u0023\u007b\u0059\u0026\u0041\u0058\u002f\u004a\u0055\u0059\u0023\u0024\u0072\u0038\u0065\u0033\u004d\u005d\u0033\u005b\u0048\u004e\u003a\u0059\u0030\u0022\u0040\u005d\u0029\u003c\u007a\u0056\u005e\u0062\u0039\u006e\u005b\u004e\u003a\u007b\u002e\u0065\u0065\u006f\u0057\u0026\u0029\u0062\u003d\u0045\u0056\u0038\u0063\u0026\u0022\u004a\u0077\u0022\u0040\u005d\u0029\u0026\u0029\u0067\u005e\u002f\u0036\u004e\u002b\u004a\u002c\u0029\u002f\u0043\u0023\u0047\u003d\u003a\u006b\u007b\u0044\u0022\u004e\u0042\u002f\u0047\u006b\u007e\u0067\u0059\u004d\u0047\u0069\u0025\u0034\u0034\u0040\u0064\u0030\u0069\u007d\u002e\u003e\u003b\u0062\u002c\u006c\u0058\u0067\u0052\u003c\u0065\u0031\u0043\u0044\u0021\u0071\u003b\u0067\u0032\u0035\u002f\u0057\u0069\u0059\u0067\u004e\u0055\u0075\u005f\u0064\u0074\u0028\u004c\u006b\u0059\u0075\u0025\u0034\u007d\u002a\u004f\u004e\u005a\u0039\u004f\u0044\u0072\u004d\u0047\u002e\u002a\u0053\u007d\u0053\u007b\u003d\u0062\u005e\u0079\u005a\u0057\u0029\u0056\u004e\u007c\u006b\u0021\u0054\u003d\u0034\u007d\u0030\u0054\u0049\u0029\u0075\u0063\u005d\u004b\u0044\u0041\u0070\u004c\u002c\u0074\u004b\u0053\u0065\u0072\u0075\u004d\u006b\u003b\u003d\u0034\u0058\u0063\u0057\u002b\u007d\u0049\u0066\u0062\u0058\u007d\u006b\u002c\u0037\u0028\u004e\u007d\u007e\u0040\u004e\u007d\u005f\u0037\u002c\u0050\u005a\u002f\u0044\u003d\u0064\u004a\u0074\u006c\u007c\u007b\u004b\u0033\u0073\u006e\u0061\u007b\u002a\u002b\u002f\u0036\u0065\u0038\u0057\u003e\u0021\u0050\u005a\u002f\u0044\u003d\u0064\u004a\u0074\u006c\u007c\u007b\u004b\u002e\u0053\u0069\u002a\u0063\u0045\u0042\u0032\u006f\u0055\u007a\u0036\u006e\u0038\u006e\u002e\u002f\u006f\u0051\u0031\u0046\u003e\u0038\u004a\u004b\u0041\u0026\u007d\u0028\u0063\u0045\u002e\u0022\u0068\u0033\u004d\u0076\u0079\u004f\u0065\u0075\u0038\u0025\u0061\u004b\u0060\u0055\u007a\u007a\u0068\u0066\u0067\u006c\u0040\u0031\u007b\u0035\u003a\u0073\u003b\u002e\u003b\u0046\u0075\u002f\u0054\u0078\u0041\u002f\u0023\u0064\u0058\u003e\u0026\u0045\u0074\u0022\u0021\u0076\u0021\u0078\u0063\u004b\u005f\u006b\u0075\u005b\u002a\u0023\u0031\u0065\u006a\u007b\u0023\u003a\u003a\u0039\u0053\u0054\u005f\u0044\u007d\u006f\u004a\u003e\u0026\u0030\u0069\u0028\u0078\u0059\u0040\u003a\u0045\u0078\u0056\u004b\u0072\u0037\u0068\u002c\u003f\u003c\u0067\u0054\u006b\u0041\u0078\u004a\u0031\u0026\u0068\u004b\u002e\u002c\u0037\u0062\u0051\u0075\u0035\u0024\u0072\u004c\u005b\u0028\u0050\u0072\u0037\u0068\u0036\u0022\u0022\u004e\u0046\u0024\u0032\u0073\u0022\u006b\u0041\u0078\u004a\u0031\u0026\u0036\u007c\u0073\u0039\u007d\u0061\u0031\u0021\u0064\u0040\u006f\u0060\u0043\u0029\u0066\u0037\u0075\u0036\u003c\u0024\u005a\u0070\u0041\u007c\u0048\u0029\u004e\u0049\u005a\u0042\u007e\u0079\u0057\u003c\u0043\u0045\u0043\u005b\u005d\u0041\u004d\u0047\u0072\u0026\u0069\u003b\u004e\u0035\u0059\u004a\u005d\u0034\u0042\u0070\u0040\u007d\u0054\u003e\u0033\u0064\u006b\u0046\u0031\u005d\u007d\u004e\u006b\u0074\u004d\u0059\u0053\u007d\u0055\u0031\u0026\u004b\u0059\u0078\u0073\u002c\u0053\u0048\u0029\u0048\u0026\u0037\u0069\u0022\u004e\u0033\u0045\u0051\u0074\u007e\u0024\u007a\u0068\u0052\u0041\u006b\u004f\u0040\u007b\u006a\u005d\u007b\u005d\u003a\u005d\u0078\u007c\u0062\u0066\u0053\u0043\u0029\u0071\u0064\u007e\u0059\u004a\u004e\u0037\u006a\u002c\u005a\u003b\u0062\u002f\u0031\u0060\u004f\u0039\u007d\u007d\u0072\u0033\u0042\u0028\u0046\u0051\u002c\u0025\u0062\u003f\u004f\u0063\u0047\u0034\u0047\u0028\u005f\u0072\u003e\u0064\u0078\u0036\u0078\u006d\u004d\u0056\u002a\u002e\u002a\u003b\u0043\u0039\u0062\u0078\u007d\u002b\u0054\u004a\u0076\u0033\u005e\u0041\u0066\u0045\u0033\u0048\u003f\u0043\u0057\u006d\u0064\u0077\u002f\u0049\u006a\u0055\u0046\u003e\u002a\u003e\u005f\u0034\u0070\u0072\u0049\u0051\u0051\u0036\u0065\u0043\u0076\u0024\u0047\u003d\u0074\u006b\u0071\u0043\u002e\u0035\u0030\u006f\u0043\u0054\u0059\u006d\u0025\u0049\u0063\u0052\u0041\u0074\u0032\u0047\u007a\u0057\u0072\u003e\u005e\u0051\u007e\u0037\u0049\u0063\u0026\u0079\u0064\u0059\u0047\u006c\u0028\u006e\u0068\u007a\u0053\u004a\u003b\u0023\u006b\u0034\u0021\u003f\u004a\u004d\u007d\u0036\u0033\u0056\u007a\u0054\u003a\u003d\u0029\u006b\u006d\u004e\u0032\u003c\u004c\u0033\u0056\u006b\u0043\u0047\u003d\u0051\u0066\u0028\u005d\u0071\u007c\u0059\u0050\u003c\u006f\u002f\u0076\u0053\u0075\u002a\u0074\u002b\u0074\u0036\u0048\u0056\u006b\u0043\u004f\u003b\u003b\u0023\u003c\u0074\u0053\u0051\u0059\u0050\u003c\u006f\u002f\u0076\u004f\u0073\u0046\u0067\u0035\u0037\u0030\u005e\u0058\u0044\u0070\u0057\u007c\u002f\u007b\u0062\u0034\u002b\u0050\u0073\u0045\u0044\u0023\u0054\u0072\u002c\u0063\u007d\u0038\u007c\u0058\u002e\u0034\u0074\u006c\u004c\u0070\u0044\u004d\u004e\u0050\u0054\u0047\u0067\u0039\u0042\u0073\u0032\u0055\u007b\u003c\u004c\u0076\u006f\u0064\u0062\u0046\u004e\u003b\u0042\u0065\u006b\u005b\u003f\u0055\u007b\u0070\u006c\u003e\u0043\u0036\u003f\u005e\u0058\u007b\u0047\u005a\u0076\u0046\u005b\u0079\u006c\u0035\u0041\u002f\u0076\u0033\u0079\u003c\u0076\u0076\u003a\u0047\u006c\u0045\u0044\u0045\u0076\u003e\u003d\u005d\u006c\u006c\u005b\u0043\u002f\u004e\u0079\u007a\u0048\u0056\u0070\u006c\u0058\u0044\u0061\u0028\u0063\u0079\u006f\u0023\u006b\u0075\u0047\u0072\u003e\u0054\u002b\u0028\u0075\u0023\u0072\u0038\u0067\u0035\u0035\u0056\u0039\u002c\u0036\u005f\u0037\u0047\u004b\u005b\u003d\u002b\u004c\u0037\u0053\u0022\u0036\u004d\u0056\u005d\u0028\u003c\u004f\u003c\u0043\u0030\u002b\u0040\u0078\u003b\u0075\u0070\u0068\u005a\u004c\u0039\u002b\u002b\u0032\u0076\u0074\u0040\u0078\u0075\u007a\u0055\u0052\u0022\u005a\u0051\u0053\u004a\u0070\u0064\u0068\u005b\u0046\u004c\u004d\u006c\u0040\u0031\u007a\u0023\u005d\u003e\u0045\u007a\u0074\u0075\u005e\u0023\u0054\u005f\u002c\u006e\u0034\u007e\u004b\u007c\u007e\u0038\u0067\u0023\u0079\u0050\u0032\u0063\u0071\u002c\u007d\u007b\u003f\u0054\u0057\u0078\u0047\u0022\u0072\u0022\u0028\u0026\u003d\u0076\u0062\u006b\u0041\u004f\u0062\u0046\u0031\u0066\u0066\u007e\u0061\u007b\u0024\u0064\u0072\u0076\u004a\u0044\u002a\u0022\u0022\u002b\u0031\u0065\u005d\u0071\u003f\u0049\u0076\u0078\u0079\u0072\u0038\u0040\u0028\u0036\u0065\u0034\u006f\u007d\u0070\u0049\u0076\u0078\u0079\u0072\u0038\u0049\u0043\u0069\u0062\u0060\u0044\u002a\u0046\u0053\u0044\u0069\u0058\u003a\u007e\u0026\u0057\u0063\u0075\u0060\u0025\u004e\u003b\u004d\u0060\u002e\u0028\u0067\u0042\u006a\u0052\u0049\u0069\u0069\u0023\u002f\u007d\u0051\u003e\u0057\u0070\u006f\u0078\u0061\u006c\u003a\u0067\u0077\u0074\u005a\u006b\u007b\u003c\u006a\u0055\u004d\u0038\u003e\u006f\u0045\u0045\u006b\u0063\u0023\u0038\u006c\u0060\u0053\u0061\u0021\u0046\u007b\u0051\u0036\u006c\u0076\u0062\u0059\u003d\u002e\u0071\u0041\u007a\u0039\u0068\u006c\u0060\u0052\u0057\u003d\u0070\u0054\u0074\u005e\u0055\u0025\u004f\u0029\u0070\u0042\u0034\u0064\u0076\u004a\u005e\u0037\u0075\u003a\u007c\u0032\u0069\u0030\u0055\u002b\u004e\u006d\u0065\u0058\u0056\u0072\u003e\u0047\u0078\u0071\u0047\u0044\u0070\u005a\u0031\u0060\u003e\u005f\u0077\u0033\u004f\u0051\u006e\u002c\u0022\u004c\u002b\u004c\u005d\u007e\u0062\u0031\u0057\u0032\u0032\u002e\u0038\u0052\u0042\u004a\u006a\u0039\u002b\u007b\u007a\u0073\u0023\u0044\u005f\u0033\u0075\u002e\u007d\u004d\u0076\u0051\u0064\u005d\u0028\u007b\u0078\u005a\u0067\u0079\u0039\u007c\u002f\u0050\u0079\u0076\u002c\u006d\u002b\u0049\u003f\u005d\u0070\u0075\u0058\u004e\u0044\u006b\u0038\u0043\u007b\u0022\u004a\u002c\u003b\u006b\u0059\u003a\u0034\u0075\u0061\u002a\u0056\u006f\u005f\u004c\u002e\u0041\u0044\u0041\u0045\u006d\u0066\u0060\u0025\u002b\u003c\u002f\u005a\u007e\u0031\u0054\u0068\u006d\u0032\u0066\u0048\u0024\u004e\u002c\u0076\u0048\u0062\u007c\u0031\u004f\u0054\u0041\u002b\u003c\u002f\u005a\u004d\u0023\u0023\u002c\u003e\u005f\u0050\u006a\u0046\u0076\u0072\u0062\u005d\u0029\u0024\u0058\u0067\u004e\u0056\u0059\u004f\u0066\u0036\u0061\u007d\u0032\u0064\u0068\u0041\u0038\u007d\u0070\u002c\u004a\u0077\u0060\u005a\u0073\u007a\u0058\u004e\u0031\u004a\u0039\u0021\u0071\u003f\u004c\u0062\u0075\u0066\u0065\u0039\u004b\u0025\u003f\u0035\u0058\u002f\u005e\u007a\u0056\u0053\u005b\u0029\u0050\u002e\u002c\u006a\u005e\u004a\u0050\u0074\u004a\u0022\u0048\u0054\u0044\u0070\u0042\u0063\u0048\u0051\u0056\u0069\u004e\u0078\u0045\u003e\u002c\u006d\u0044\u0067\u003c\u002e\u0063\u006b\u004f\u0053\u007e\u004f\u0074\u0034\u0053\u0078\u0078\u0023\u0045\u0024\u0043\u002c\u0052\u0062\u0039\u002e\u0041\u0038\u002a\u0032\u005f\u0057\u0058\u004f\u0038\u005f\u005e\u0053\u0068\u007d\u004d\u0025\u0054\u002f\u0048\u004e\u0067\u002b\u0041\u0036\u007a\u007e\u0052\u0060\u0026\u0025\u0035\u0041\u005a\u0064\u003f\u0045\u0068\u0062\u0075\u0065\u0048\u0075\u0028\u0056\u006e\u0059\u0063\u0077\u0054\u006e\u005b\u0059\u0060\u0046\u0040\u005a\u0052\u0075\u0068\u006f\u002b\u004a\u0072\u0074\u0055\u0073\u0033\u006f\u002a\u0031\u0031\u0036\u0028\u0033\u005f\u0033\u002e\u002a\u0067\u007a\u004d\u0075\u0036\u0060\u0037\u0026\u007a\u0029\u0046\u007a\u0021\u0023\u006d\u002e\u0031\u005d\u0065\u0040\u005a\u005a\u0037\u0064\u0073\u005b\u0026\u0064\u004c\u004e\u0075\u0037\u0053\u0029\u004a\u0052\u0070\u003f\u0069\u0069\u0078\u0066\u004d\u0045\u007e\u0071\u0052\u0077\u0026\u002e\u0073\u0054\u0058\u0023\u0034\u007d\u0045\u003a\u0060\u0021\u006b\u0056\u006f\u0044\u0048\u0046\u0035\u0054\u0055\u0061\u007c\u0066\u007c\u0022\u002e\u007d\u0032\u004a\u0062\u003b\u0039\u0079\u0046\u0045\u003e\u0023\u0079\u006b\u002c\u004a\u0028\u0079\u0029\u0054\u0049\u0043\u003a\u0038\u0042\u0054\u0030\u0076\u004e\u0040\u0054\u0034\u0051\u003a\u005a\u002e\u0074\u0061\u0050\u005d\u005f\u002f\u0047\u0053\u004d\u004f\u0022\u0067\u0034\u004e\u0042\u002e\u0061\u005f\u0046\u0041\u0062\u0028\u0045\u0053\u0025\u005a\u0030\u0041\u005f\u0045\u0040\u004c\u002b\u002b\u0039\u0025\u0074\u0063\u0040\u003a\u005f\u0068\u0034\u005b\u007b\u007d\u0077\u0046\u0038\u0079\u006b\u006b\u0039\u0030\u003d\u0070\u0025\u0033\u002f\u005b\u0046\u0042\u0072\u0045\u005f\u006e\u0069\u005e\u0045\u0072\u0061\u0079\u002a\u002e\u005d\u0064\u002b\u007c\u0023\u0068\u0031\u0041\u0060\u0029\u0037\u006f\u0045\u0062\u0070\u0051\u0075\u003c\u0077\u003b\u0062\u0026\u003e\u0026\u0032\u002e\u0066\u0056\u005d\u0061\u005b\u0061\u0079\u0066\u005a\u007c\u0025\u0058\u005e\u0073\u006b\u0033\u007b\u005f\u0075\u0038\u0034\u0044\u0046\u004b\u003d\u0079\u0022\u0036\u006f\u003a\u0065\u004f\u003e\u004a\u0076\u0046\u003d\u0026\u0026\u006f\u006f\u0058\u0072\u004a\u003b\u0031\u003e\u007c\u0059\u0032\u0025\u0045\u0067\u0048\u0054\u004d\u0072\u004a\u003b\u0031\u003e\u007c\u0072\u0053\u0053\u006d\u0076\u005b\u006a\u0045\u0072\u0061\u0079\u002a\u002e\u0066\u0043\u0044\u0066\u0042\u0036\u0045\u0037\u007a\u007c\u0030\u0067\u003c\u007a\u0060\u003d\u0022\u003d\u0037\u005f\u002c\u0030\u0021\u0053\u0024\u002b\u003a\u0042\u0069\u003e\u0040\u003e\u0048\u0035\u0055\u0047\u005b\u005d\u002b\u0064\u0025\u0046\u002f\u004c\u0046\u0024\u0069\u0079\u002a\u0059\u0058\u004d\u0057\u0022\u0063\u005e\u0070\u0065\u0048\u0062\u0061\u006c\u005e\u0050\u0068\u004a\u0056\u0070\u0047\u0042\u003c\u0040\u007c\u006d\u0048\u0064\u0075\u0051\u0025\u005a\u004b\u0057\u002b\u0031\u0067\u0029\u002b\u0054\u0037\u0021\u0037\u004f\u0032\u0025\u0046\u0024\u0062\u0046\u0024\u0069\u0079\u002a\u0059\u0058\u004d\u0057\u0022\u0063\u005e\u0070\u0065\u0048\u0062\u0038\u0036\u0051\u0072\u0055\u0079\u003c\u006d\u005e\u004f\u0039\u0067\u0064\u0044\u0047\u003e